INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7646021, 1243000, 141319, '<td valign="top">Well done - I totally get this :-). Whether or not the voter is afraid of spiders, the picture clearly tells the story that the subject is - good photo, clear interpretation of the theme - 10 from me - good luck.</td>', 'Well done - I totally get this :-). Whether or not the voter is afraid of spiders, the picture clearly tells the story that the subject is - good photo, clear interpretation of the theme - 10 from me - good luck.', '2019-11-11 01:49:51.000000', NULL, 1),
(7646022, 1242981, 141319, '<td valign="top">That little boys face says "fear" to me, whether or not this is a rehearsed "trick". well done on spotting this. Good luck in the challenge.</td>', 'That little boys face says "fear" to me, whether or not this is a rehearsed "trick". well done on spotting this. Good luck in the challenge.', '2019-11-11 01:51:15.000000', NULL, 1),
(7646023, 1242983, 141319, '<td valign="top">Great image, however, it will only say "fear" to people who fear creepy-crawlies. I was a bit betwixed and between in my score on this, decided in the and to take it the "alien" route and give you a "9", I think your intention was made clear by using the mono and going low key as well as the "scary" claws and unknown creature. Good luck in the challenge</td>', 'Great image, however, it will only say "fear" to people who fear creepy-crawlies. I was a bit betwixed and between in my score on this, decided in the and to take it the "alien" route and give you a "9", I think your intention was made clear by using the mono and going low key as well as the "scary" claws and unknown creature. Good luck in the challenge', '2019-11-11 01:55:18.000000', NULL, 1),
(7646024, 1242955, 141319, '<td valign="top">Great expression of "fear". Excellent image for this challenge, good luck.</td>', 'Great expression of "fear". Excellent image for this challenge, good luck.', '2019-11-11 01:55:46.000000', NULL, 1),
(7646025, 1243004, 141319, '<td valign="top">This for me was a very interesting image. Your use of movement/blur really added to making this "scary" and be on topic for the challenge. I doubt the mask alone would have worked. Great work, Good luck.</td>', 'This for me was a very interesting image. Your use of movement/blur really added to making this "scary" and be on topic for the challenge. I doubt the mask alone would have worked. Great work, Good luck.', '2019-11-11 01:59:30.000000', NULL, 1),
(7646026, 1242995, 141319, '<td valign="top">Nice image, creative but clear interpretation of the theme.</td>', 'Nice image, creative but clear interpretation of the theme.', '2019-11-11 02:00:17.000000', NULL, 1),
(7646027, 1242969, 141319, '<td valign="top">Nice image. Creative interpretation.</td>', 'Nice image. Creative interpretation.', '2019-11-11 02:02:26.000000', NULL, 1),
(7646028, 1242745, 141319, '<td valign="top">Ok, it made me laugh, I am not sure a "fear" image should make me laugh, but it has all the elements of "fear", just a comic interpretation of the theme. Interesting take ....</td>', 'Ok, it made me laugh, I am not sure a "fear" image should make me laugh, but it has all the elements of "fear", just a comic interpretation of the theme. Interesting take ....', '2019-11-11 02:04:45.000000', NULL, 1),
(7646029, 1242948, 141319, '<td valign="top">Classic "fear". Well done, I expected more of those actually :-).</td>', 'Classic "fear". Well done, I expected more of those actually :-).', '2019-11-11 02:05:28.000000', NULL, 1),
(7646031, 1242650, 141319, '<td valign="top">This image is really "creepy" great post. 9 from me, good luck</td>', 'This image is really "creepy" great post. 9 from me, good luck', '2019-11-11 02:06:06.000000', NULL, 1),
(7646032, 1243014, 141319, '<td valign="top">Love the way you photographed this.</td>', 'Love the way you photographed this.', '2019-11-11 02:06:42.000000', NULL, 1),
(7646033, 1242994, 141319, '<td valign="top">I am not convinced by the model, but then I don''t relate to this type of fear. To me he looks content rather than fearful, but I probably project my own feelings into this. I like the idea and the way you handled the image, it just doesn''t portrait "fear" to me.</td>', 'I am not convinced by the model, but then I don''t relate to this type of fear. To me he looks content rather than fearful, but I probably project my own feelings into this. I like the idea and the way you handled the image, it just doesn''t portrait "fear" to me.', '2019-11-11 02:08:39.000000', NULL, 1),
(7646034, 1242910, 141319, '<td valign="top">There were several images in this challenge that did not "show" fear to me, unless you had the fear that was portrayed. I am not sure if this is fear of drowning, or fear of unknown places, or whatever, but as the viewer I don''t share those fears and can''t relate to the image for the challenge. I am not sure I have expressed myself clearly, I just wanted you to understand why I did not score this high. The image is interesting/good in itself, just not for this challenge (my opinion only of course).</td>', 'There were several images in this challenge that did not "show" fear to me, unless you had the fear that was portrayed. I am not sure if this is fear of drowning, or fear of unknown places, or whatever, but as the viewer I don''t share those fears and can''t relate to the image for the challenge. I am not sure I have expressed myself clearly, I just wanted you to understand why I did not score this high. The image is interesting/good in itself, just not for this challenge (my opinion only of course).', '2019-11-11 02:11:57.000000', NULL, 1),
(7646035, 1242810, 141319, '<td valign="top">There were several images in this challenge that did not "show" fear to me, unless you had the fear that was portrayed. I don''t have a fear of clowns, I know it exists, just not for me. A bright image with a smiling clown doesn''t hit the "fear" spot for me and I can''t relate to the image for the challenge. If you had a person "reacting" fearful to the clown I think it would have worked. I am not sure I have expressed myself clearly, I just wanted you to understand why I did not score this high. The image is good in itself, just not for this challenge (my opinion only of course).</td>', 'There were several images in this challenge that did not "show" fear to me, unless you had the fear that was portrayed. I don''t have a fear of clowns, I know it exists, just not for me. A bright image with a smiling clown doesn''t hit the "fear" spot for me and I can''t relate to the image for the challenge. If you had a person "reacting" fearful to the clown I think it would have worked. I am not sure I have expressed myself clearly, I just wanted you to understand why I did not score this high. The image is good in itself, just not for this challenge (my opinion only of course).', '2019-11-11 02:14:51.000000', NULL, 1),
(7646036, 1242932, 141319, '<td valign="top">Ummm, interesting angle to the  challenge, however, to me the kitty doesn''t really show fear, it looks like it is meowing. If you had captured it with a hunched back and hairs up this may have worked.</td>', 'Ummm, interesting angle to the  challenge, however, to me the kitty doesn''t really show fear, it looks like it is meowing. If you had captured it with a hunched back and hairs up this may have worked.', '2019-11-11 02:16:32.000000', NULL, 1),
(7646037, 1242913, 141319, '<td valign="top">IMO, the way you photographed this is brilliant. the reflections make it "spooky" even though the actual subject is not that scary (IMO). well done!</td>', 'IMO, the way you photographed this is brilliant. the reflections make it "spooky" even though the actual subject is not that scary (IMO). well done!', '2019-11-11 02:18:01.000000', NULL, 1),
(7646038, 1242968, 141319, '<td valign="top">I am not sure what to give you on this :-). Such an interesting angle to this challenge and well photographed. I think I will come back to adjust my score upwards :-).</td>', 'I am not sure what to give you on this :-). Such an interesting angle to this challenge and well photographed. I think I will come back to adjust my score upwards :-).', '2019-11-11 02:19:48.000000', NULL, 1),
(7646039, 1242976, 141319, '<td valign="top">I am sorry, but I don''t understand this image. You have clearly put much thought into this, but for me its people waiting. I don''t get the fear aspect. I am sorry :-(.</td>', 'I am sorry, but I don''t understand this image. You have clearly put much thought into this, but for me its people waiting. I don''t get the fear aspect. I am sorry :-(.', '2019-11-11 02:21:32.000000', NULL, 1),
(7646040, 1242656, 141319, '<td valign="top">There were several images in this challenge that did not "show" fear to me, unless you had the fear that was portrayed. I am not sure if this is fear of dying, or fear of the unknown after death, or whatever, but as the viewer I don''t share those fears and can''t relate to the image for the challenge. In addition, the bright light is "positive" for me rather than "negative" (fear). I am not sure I have expressed myself clearly, I just wanted you to understand why I did not score this high. The image is interesting/good in itself, just not for this challenge (my opinion only of course).</td>', 'There were several images in this challenge that did not "show" fear to me, unless you had the fear that was portrayed. I am not sure if this is fear of dying, or fear of the unknown after death, or whatever, but as the viewer I don''t share those fears and can''t relate to the image for the challenge. In addition, the bright light is "positive" for me rather than "negative" (fear). I am not sure I have expressed myself clearly, I just wanted you to understand why I did not score this high. The image is interesting/good in itself, just not for this challenge (my opinion only of course).', '2019-11-11 02:23:57.000000', NULL, 1),
(7646041, 1242954, 141319, '<td valign="top">There were several images in this challenge that did not "show" fear to me, unless you had the fear that was portrayed. I am not sure if this is fear of heights, but as the viewer I don''t share those fears and can''t relate to the image for the challenge. To me this is a landscape image. I am not sure I have expressed myself clearly, I just wanted you to understand why I did not score this high. The image is interesting/good in itself, just not for this challenge (my opinion only of course).</td>', 'There were several images in this challenge that did not "show" fear to me, unless you had the fear that was portrayed. I am not sure if this is fear of heights, but as the viewer I don''t share those fears and can''t relate to the image for the challenge. To me this is a landscape image. I am not sure I have expressed myself clearly, I just wanted you to understand why I did not score this high. The image is interesting/good in itself, just not for this challenge (my opinion only of course).', '2019-11-11 02:25:09.000000', NULL, 1),
(7646042, 1243011, 141319, '<td valign="top">There were several images in this challenge that did not "show" fear to me, unless you had the fear that was portrayed. I am not sure if this is fear of being lost (title), or fear of unknown places, or whatever, but as the viewer I don''t share those fears and can''t relate to the image for the challenge. I am not sure I have expressed myself clearly, I just wanted you to understand why I did not score this high. The image is interesting in itself, just not for this challenge (my opinion only of course).</td>', 'There were several images in this challenge that did not "show" fear to me, unless you had the fear that was portrayed. I am not sure if this is fear of being lost (title), or fear of unknown places, or whatever, but as the viewer I don''t share those fears and can''t relate to the image for the challenge. I am not sure I have expressed myself clearly, I just wanted you to understand why I did not score this high. The image is interesting in itself, just not for this challenge (my opinion only of course).', '2019-11-11 02:25:50.000000', NULL, 1),
(7646043, 1242984, 141319, '<td valign="top">I am sorry, I don''t get this image for this challenge :-(. I live in a "barren" country, for me the image is positively well covered :-), and I don''t get the "fractured" ... I just wanted you to understand why I scored this low. For me the image is of a landscape, nothing to fear in there.</td>', 'I am sorry, I don''t get this image for this challenge :-(. I live in a "barren" country, for me the image is positively well covered :-), and I don''t get the "fractured" ... I just wanted you to understand why I scored this low. For me the image is of a landscape, nothing to fear in there.', '2019-11-11 02:28:03.000000', NULL, 1),
(7646044, 1242989, 141319, '<td valign="top">There were several images in this challenge that did not "show" fear to me, unless you had the fear that was portrayed. I am not sure if this is fear of dying, or fear of the future, or of unknown places, or whatever, but as the viewer I don''t share those fears and can''t relate to the image for the challenge. I am not sure I have expressed myself clearly, I just wanted you to understand why I did not score this high. The image is interesting/good in itself (what a beautiful gate, I would love to have that :-)), just not for this challenge (my opinion only of course).</td>', 'There were several images in this challenge that did not "show" fear to me, unless you had the fear that was portrayed. I am not sure if this is fear of dying, or fear of the future, or of unknown places, or whatever, but as the viewer I don''t share those fears and can''t relate to the image for the challenge. I am not sure I have expressed myself clearly, I just wanted you to understand why I did not score this high. The image is interesting/good in itself (what a beautiful gate, I would love to have that :-)), just not for this challenge (my opinion only of course).', '2019-11-11 02:29:19.000000', NULL, 1),
(7646045, 1243003, 141319, '<td valign="top">I appreciate your attempt at portraying a "feeling" in an abstract way. Unfortunately for me this didn''t work.</td>', 'I appreciate your attempt at portraying a "feeling" in an abstract way. Unfortunately for me this didn''t work.', '2019-11-11 02:34:55.000000', NULL, 1),
(7646046, 1242602, 141319, '<td valign="top">There were several images in this challenge that did not "show" fear to me, unless you had the fear that was portrayed. As the viewer I don''t share this fear and can''t relate to the image for the challenge. Had you shown a person expressing the fear in your image it would have been clear. I am not sure I have expressed myself well, I just wanted you to understand why I did not score this high. The image is interesting/good in itself, just not for this challenge (my opinion only of course).</td>', 'There were several images in this challenge that did not "show" fear to me, unless you had the fear that was portrayed. As the viewer I don''t share this fear and can''t relate to the image for the challenge. Had you shown a person expressing the fear in your image it would have been clear. I am not sure I have expressed myself well, I just wanted you to understand why I did not score this high. The image is interesting/good in itself, just not for this challenge (my opinion only of course).', '2019-11-11 02:36:17.000000', NULL, 1),
